70	 */
71	export const ZimmQuantityStepper = ({
72	  quantity,
73	  min = MIN_DEFAULT,
74	  max,
75	  isUnavailable = false,
76	  onDecrement,
77	  onIncrement,
78	  ariaDescribedBy,
79	}: ZimmQuantityStepperProps) => {
80	  const intl = useIntl();
81	  const styles = useMultiStyleConfig('ZimmQuantityStepper', { disabled: isUnavailable });
82	
83	  const decrementInert = isUnavailable || quantity <= min;
84	  const incrementInert = isUnavailable || quantity >= max;
85	
86	  const handleDecrement = () => {
87	    if (decrementInert) return;
88	    onDecrement(quantity - 1);
89	  };
90	
91	  const handleIncrement = () => {
92	    if (incrementInert) return;
93	    onIncrement(quantity + 1);
94	  };
95	
96	  return (
97	    <chakra.div __css={styles.root}>
98	      <ZimmButton
