102	        ariaDisabled={decrementInert}
103	        ariaDescribedBy={ariaDescribedBy}
104	        onClick={handleDecrement}
105	      />
106	      {/* aria-live: a shopper-caused change to their own just-clicked control still benefits
107	          screen reader users exploring the surrounding value, not just the button they pressed. */}
108	      <chakra.span __css={styles.value} aria-live="polite">
109	        {quantity}
110	      </chakra.span>
111	      <ZimmButton
112	        variant="icon"
113	        icon="plus"
114	        label={intl.formatMessage(messages.increment)}
115	        ariaDisabled={incrementInert}
116	        ariaDescribedBy={ariaDescribedBy}
117	        onClick={handleIncrement}
118	      />
119	    </chakra.div>
120	  );
121	};
